/**
 * Express Checkout (Apple Pay / Google Pay / Link) on classic shortcode checkout.
 *
 * Mounts above the gateway payment form. On confirm:
 *  1. POST /dokan/v1/stripe-connect/payment-intent → client_secret + intent_id
 *  2. stripe.confirmPayment({ elements, clientSecret, return_url }) inside wallet
 *  3. append hidden `dokan_stripe_payment_intent_id` to the WC checkout form
 *  4. submit the form — server-side process_payment routes to process_payment_via_pi
 *
 * @since 5.0.7
 */
import { createRoot, useMemo, useState } from '@wordpress/element';
import domReady from '@wordpress/dom-ready';
import { type Stripe, type StripeElementsOptions } from '@stripe/stripe-js';
import {
    Elements,
    ExpressCheckoutElement,
    useStripe,
    useElements,
} from '@stripe/react-stripe-js';

import {
    appendIntentId,
    fetchPaymentIntent,
    isCheckoutPage,
    isProductPage,
    loadStripeOnce,
    params,
    resetPaymentIntent,
    submitWalletCheckout,
    wcAjaxPost,
} from './shared';

const MOUNT_ID = 'dokan-stripe-connect-express-checkout';

const readProductIdFromContainer = (): number => {
    const container = document.getElementById( MOUNT_ID );
    const raw = container?.dataset.productId ?? '0';
    return parseInt( raw, 10 ) || 0;
};

const addProductToCart = async (): Promise< void > => {
    const productId = readProductIdFromContainer();
    if ( ! productId ) {
        return;
    }
    const qtyInput = document.querySelector< HTMLInputElement >(
        'form.cart input[name="quantity"]'
    );
    const quantity = qtyInput ? parseInt( qtyInput.value, 10 ) || 1 : 1;
    await wcAjaxPost( 'add_to_cart', { product_id: productId, quantity } );
};

const submitCheckoutForm = ( intentId: string ): boolean => {
    const form = document.querySelector< HTMLFormElement >(
        'form.woocommerce-checkout'
    );
    if ( ! form || ! isCheckoutPage() ) {
        return false;
    }

    appendIntentId( form, intentId );

    const radio = document.querySelector< HTMLInputElement >(
        'input[name="payment_method"][value="dokan-stripe-connect"]'
    );
    if ( radio ) {
        radio.checked = true;
    }

    // Bypass the classic PE confirmPayment handler — wallet already confirmed.
    ( window as any )
        .jQuery?.( form )
        .off( 'checkout_place_order_dokan-stripe-connect' );

    form.submit();
    return true;
};

const InnerExpress = () => {
    const stripe = useStripe();
    const elements = useElements();
    const [ submitting, setSubmitting ] = useState( false );

    const handleConfirm = async ( event: any ) => {
        if ( ! stripe || ! elements || submitting ) {
            return;
        }

        event?.preventDefault?.();
        setSubmitting( true );

        try {
            if ( isProductPage() ) {
                await addProductToCart();
            }

            const { error: submitError } = await elements.submit();
            if ( submitError ) {
                throw new Error(
                    submitError.message || 'Elements submit failed'
                );
            }

            resetPaymentIntent();
            const intent = await fetchPaymentIntent();
            if ( ! intent ) {
                throw new Error( 'payment-intent request failed' );
            }

            const { error } = await stripe.confirmPayment( {
                elements,
                clientSecret: intent.client_secret,
                confirmParams: {
                    return_url: params.return_url || window.location.href,
                },
                redirect: 'if_required',
            } );

            if ( error ) {
                throw new Error(
                    error.message || 'Wallet confirmation failed'
                );
            }

            // On the checkout page, submit the existing form so server-side
            // checkout flow runs natively. Otherwise (product / cart pages)
            // POST to `?wc-ajax=checkout` directly with the wallet billing
            // info so the order is placed without bouncing through checkout.
            if ( submitCheckoutForm( intent.intent_id ) ) {
                return;
            }

            const result = await submitWalletCheckout(
                intent.intent_id,
                event,
                params.checkout_nonce ?? ''
            );
            if ( result.ok ) {
                window.location.assign( result.redirect );
                return;
            }

            throw new Error( result.message );
        } catch ( e: any ) {
            // eslint-disable-next-line no-console
            console.warn( '[Dokan Stripe Express]', e?.message );
            // eslint-disable-next-line no-alert
            window.alert( e?.message || 'Express checkout failed' );
            setSubmitting( false );
        }
    };

    const handleReady = ( event: any ) => {
        const available = event?.availablePaymentMethods;
        const anyWallet =
            available && Object.values( available ).some( ( v ) => v === true );

        const container = document.getElementById( MOUNT_ID );
        const wrap = container?.closest< HTMLElement >(
            '.dokan-stripe-pe-express-wrap'
        );

        if ( ! anyWallet ) {
            // eslint-disable-next-line no-console
            console.info(
                '[Dokan Stripe Express] No wallet detected. availablePaymentMethods =',
                available
            );
            wrap?.classList.add( 'is-empty' );
            return;
        }

        wrap?.classList.add( 'is-ready' );
    };

    return (
        <>
            { submitting && (
                <div className="dokan-stripe-pe-express-loading-overlay">
                    <div
                        className="dokan-stripe-pe-express-spinner"
                        aria-hidden="true"
                    />
                </div>
            ) }
            <ExpressCheckoutElement
                onConfirm={ handleConfirm }
                onReady={ handleReady }
                options={ {
                    buttonType: { applePay: 'buy', googlePay: 'buy' },
                    paymentMethods: {
                        applePay: 'always',
                        googlePay: 'always',
                    },
                    emailRequired: true,
                    billingAddressRequired: true,
                    phoneNumberRequired: true,
                    shippingAddressRequired: false,
                } }
            />
        </>
    );
};

const Mount = () => {
    const stripePromise: Promise< Stripe | null > | null = useMemo(
        loadStripeOnce,
        []
    );

    const amount = Number( params.cart_total_minor );
    if ( ! amount || amount <= 0 ) {
        return null;
    }

    const elementOptions: StripeElementsOptions = {
        mode: 'payment',
        amount,
        currency: ( params.currency ?? 'usd' ).toLowerCase(),
        appearance: { theme: 'stripe' },
        loader: 'auto',
    };

    // Deferred-intent Elements must declare the same setup_future_usage the
    // server stamps on the PaymentIntent, or confirmPayment rejects with a
    // mismatch. Server sends 'off_session' when the cart should save the card.
    if (
        params.setup_future_usage === 'off_session' ||
        params.setup_future_usage === 'on_session'
    ) {
        elementOptions.setupFutureUsage = params.setup_future_usage;
    }

    return (
        <Elements stripe={ stripePromise } options={ elementOptions }>
            <InnerExpress />
        </Elements>
    );
};

// React root cache. WC may replace the gateway DOM on `updated_checkout` — we
// detect identity changes and recreate the root only then so cart-total
// refreshes don't trigger React 18's "createRoot called twice" warning.
let expressRoot: ReturnType< typeof createRoot > | null = null;
let mountedContainer: HTMLElement | null = null;

const mountExpress = () => {
    const container = document.getElementById( MOUNT_ID );
    if ( ! container ) {
        return;
    }

    if ( container !== mountedContainer ) {
        if ( expressRoot ) {
            try {
                expressRoot.unmount();
            } catch {
                // old container may already be detached.
            }
        }
        expressRoot = createRoot( container );
        mountedContainer = container;
    }

    expressRoot?.render( <Mount /> );
};

domReady( () => {
    mountExpress();

    ( window as any ).jQuery?.( document.body ).on( 'updated_checkout', () => {
        mountExpress();
    } );
} );
