/**
 * Shared REST client for the Dokan Stripe Connect endpoints.
 *
 * Used by every Stripe frontend bundle — classic Payment Element, classic
 * Express Checkout, and the block-checkout payment method. Each endpoint call
 * is deduped per bundle via an in-flight promise cache so concurrent callers
 * (PE mount + Express confirm + block PI fetch) collapse to one POST.
 *
 * @since 5.0.7
 */

// @ts-ignore — wp-scripts provides @wordpress/api-fetch externally.
import apiFetch from '@wordpress/api-fetch';

const REST_BASE = '/dokan/v1/stripe-connect';

export type IntentType = 'payment' | 'setup';

export type PaymentIntentResponse = {
    type: IntentType;
    client_secret: string;
    intent_id: string;
    /** Present for DPS (Dokan Product Subscription) flow only. */
    subscription_id?: string;
};

export type VerifyIntentResponse = {
    redirect: string;
};

let paymentIntentPromise: Promise< PaymentIntentResponse | null > | null = null;

/**
 * POST /stripe-connect/payment-intent → mint or refresh the platform PI.
 *
 * Deduped per bundle so PE classic + Express + block bundles each issue at
 * most one POST per page load.
 *
 * @param args
 * @param args.context
 * @param args.amount
 * @param args.order_id
 * @param args.order_key
 */
export const fetchPaymentIntent = ( args?: {
    context?: 'add_payment_method' | 'order_pay';
    amount?: number;
    order_id?: number;
    order_key?: string;
} ): Promise< PaymentIntentResponse | null > => {
    if ( paymentIntentPromise ) {
        return paymentIntentPromise;
    }
    paymentIntentPromise = ( async () => {
        try {
            const json = ( await apiFetch( {
                path: `${ REST_BASE }/payment-intent`,
                method: 'POST',
                data: args,
            } ) ) as Partial< PaymentIntentResponse >;

            if ( ! json?.client_secret || ! json?.intent_id ) {
                paymentIntentPromise = null;
                return null;
            }
            const type: IntentType =
                json.type === 'setup' ? 'setup' : 'payment';
            return {
                type,
                client_secret: json.client_secret,
                intent_id: json.intent_id,
                subscription_id: json.subscription_id,
            };
        } catch ( e: any ) {
            // eslint-disable-next-line no-console
            console.warn(
                '[Dokan Stripe]',
                e?.message ?? 'payment-intent request failed'
            );
            paymentIntentPromise = null;
            return null;
        }
    } )();
    return paymentIntentPromise;
};

/**
 * Reset the in-flight PI cache. Call after a failed confirm or when the cart
 * changes so the next consumer mints a fresh intent.
 */
export const resetPaymentIntent = (): void => {
    paymentIntentPromise = null;
};

/**
 * POST /stripe-connect/verify-intent → settle an order after an SCA redirect.
 *
 * @param orderId  WooCommerce order id.
 * @param intentId Stripe PaymentIntent id.
 */
export const verifyIntent = async (
    orderId: number,
    intentId: string
): Promise< VerifyIntentResponse | null > => {
    try {
        const json = ( await apiFetch( {
            path: `${ REST_BASE }/verify-intent`,
            method: 'POST',
            data: { order_id: orderId, intent_id: intentId },
        } ) ) as Partial< VerifyIntentResponse >;
        if ( ! json?.redirect ) {
            return null;
        }
        return { redirect: json.redirect };
    } catch ( e: any ) {
        // eslint-disable-next-line no-console
        console.warn(
            '[Dokan Stripe]',
            e?.message ?? 'verify-intent request failed'
        );
        return null;
    }
};
